import {createLyrics} from './lyrics.js?v=9';
import * as vault from './vault.js?v=9';
const $=s=>document.querySelector(s);
const localMotorHost=['localhost','127.0.0.1'].includes(location.hostname);
let ctx,musicGain,filters,output,recordBus,recordMix,micStream,micSource,micGain,micMonitor,analyser;
let engineActiveJob=null;
let karaokeMusic=null,karaokeVoice=null,preparedSignature=null;
let recordSaving=false,layerBuffer=null,layerSource=null,layerGain=null;
let original,prepared,currentBlob,title='',songId=null,shift=0,source=null,playing=false,position=0,started=0,busy=false,worker,recorder,recording=false,loadToken=0;
const urls=[];
const say=(message,error=false)=>{ $('#status').textContent=message;$('#status').classList.toggle('error',error); };
const time=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function cleanLimiter(c){const n=c.createDynamicsCompressor();n.threshold.value=-3;n.knee.value=0;n.ratio.value=20;n.attack.value=.003;n.release.value=.15;return n;}
function init(){if(ctx)return;ctx=new AudioContext();recordBus=ctx.createMediaStreamDestination();output=cleanLimiter(ctx);output.connect(ctx.destination);recordMix=cleanLimiter(ctx);recordMix.connect(recordBus);output.connect(recordMix);musicGain=ctx.createGain();musicGain.gain.value=.7;filters=makeEq(ctx);filters[2].connect(musicGain).connect(output);}
function makeEq(c){const a=[c.createBiquadFilter(),c.createBiquadFilter(),c.createBiquadFilter()];a[0].type='lowshelf';a[0].frequency.value=180;a[1].type='peaking';a[1].frequency.value=1800;a[1].Q.value=.8;a[2].type='highshelf';a[2].frequency.value=6000;for(let i=0;i<3;i++)a[i].gain.value=Number($(['#low','#mid','#high'][i]).value);a[0].connect(a[1]).connect(a[2]);return a;}
function controls(){const ready=!!prepared&&!busy;for(const id of ['play','restart','seek','tools','saveSong','downloadTrack','prepareAI'])$('#'+id).disabled=!ready||recording;$('#record').disabled=!ready||!micStream||recording||recordSaving;$('#mic').disabled=recording||recordSaving;$('#file').disabled=recording||busy;$('#demo').disabled=recording||busy;$('#up').disabled=shift>=6;$('#down').disabled=shift<=-6;$('#logout').disabled=recording||recordSaving||busy;$('#backup').disabled=recording||recordSaving||busy;$('#play').textContent=playing?'Ⅱ Pausar pista':'▶ Escuchar pista';$('#record').hidden=recording;$('#stopRecord').hidden=!recording;if(!localMotorHost){$('#prepareAI').disabled=true;$('#up').disabled=true;$('#down').disabled=true;$('#resetTone').disabled=true;$('#voiceBlend').disabled=shift!==0||!karaokeMusic;$('#mode').disabled=shift!==0||!karaokeMusic;}}
function current(){return playing?Math.min(prepared.duration,position+ctx.currentTime-started):position;}
function pause(){stopLayer();if(!playing)return;position=current();source.onended=null;source.stop();source.disconnect();source=null;playing=false;controls();}
async function play(){if(!prepared||busy)return;init();await ctx.resume();if(position>=prepared.duration)position=0;source=ctx.createBufferSource();source.buffer=prepared;source.connect(filters[0]);started=ctx.currentTime;playing=true;source.onended=()=>{stopLayer();playing=false;position=0;source=null;if(recording)finishRecording();controls();};source.start(0,position);startLayer(position);controls();}
function stop(){pause();position=0;}
function settings(){return{shift,mode:$('#mode').value,low:Number($('#low').value),mid:Number($('#mid').value),high:Number($('#high').value),volume:Number($('#musicVolume').value),layerVolume:Number($('#layerVolume').value),voiceBlend:Number($('#voiceBlend').value)};}
function signature(){return JSON.stringify({shift,mode:$('#mode').value,voiceBlend:Number($('#voiceBlend').value)});}
async function engineJob(task,buffer,semitones=0){
 if(!localMotorHost)throw Error("La preparación con IA y los tonos nuevos se hacen en la edición de computadora. Importá una pista preparada o una copia cifrada de tu repertorio.");
 let id,engine;
 try{const statusResponse=await fetch('./api/engine',{cache:'no-store'});if(!statusResponse.ok)throw Error();engine=await statusResponse.json();if(!(task==='separate'?engine.separation:engine.pitch))throw Error('Ejecutá INSTALAR-MOTOR.bat en esta computadora para preparar el motor local.');}
 catch(e){throw Error(e.message.includes('INSTALAR')?e.message:'El motor local no está disponible. Abrí MixLab con COMENZAR.bat; para cambiar el tono o separar por primera vez necesitás el motor instalado.');}
 const headers={'Content-Type':'audio/wav','X-MixLab-Engine':engine.token};
 try{const response=await fetch('./api/engine/jobs?task='+task+'&semitones='+semitones,{method:'POST',headers,body:wav(buffer)}),data=await response.json();if(!response.ok)throw Error(data.error);id=data.id;engineActiveJob={id,headers};$('#cancelEngine').hidden=false;const started=Date.now();
  while(true){const r=await fetch('./api/engine/jobs/'+id,{headers,cache:'no-store'}),job=await r.json();if(!r.ok||job.state==='error')throw Error(job.error||job.message);say(job.message+' La canción original sigue guardada.');if(job.state==='done')break;if(Date.now()-started>45*60*1000)throw Error('La preparación demoró demasiado. Probá una canción más corta.');await new Promise(resolve=>setTimeout(resolve,1800));}
  const names=task==='separate'?['instrumental','vocals']:['result'];const blobs=[];for(const name of names){const r=await fetch('./api/engine/jobs/'+id+'/'+name,{headers});if(!r.ok)throw Error('No se pudo recuperar la pista preparada.');blobs.push(await r.blob());}return blobs;
 }finally{engineActiveJob=null;$('#cancelEngine').hidden=true;if(id)await fetch('./api/engine/jobs/'+id,{method:'DELETE',headers}).catch(()=>{});}
}
async function restoreKaraoke(){karaokeMusic=null;karaokeVoice=null;preparedSignature=null;if(!songId)return;const i=await vault.getItem('stem-i:'+songId),v=await vault.getItem('stem-v:'+songId);if(i&&v){karaokeMusic=await ctx.decodeAudioData(await i.blob.arrayBuffer());karaokeVoice=await ctx.decodeAudioData(await v.blob.arrayBuffer());}}
async function ensureKaraoke(){if(karaokeMusic&&karaokeVoice)return;const files=await engineJob('separate',original);const music=await ctx.decodeAudioData(await files[0].arrayBuffer()),voice=await ctx.decodeAudioData(await files[1].arrayBuffer());await vault.putItem('stem','stem-i:'+songId,{role:'instrumental'},files[0]);await vault.putItem('stem','stem-v:'+songId,{role:'vocals'},files[1]);karaokeMusic=music;karaokeVoice=voice;}
function mixedStem(){const mode=$('#mode').value;if(mode==='original')return original;if(mode==='guide')return karaokeVoice;const mix=ctx.createBuffer(2,karaokeMusic.length,karaokeMusic.sampleRate),level=Number($('#voiceBlend').value)/100;for(let c=0;c<2;c++){const out=mix.getChannelData(c),music=karaokeMusic.getChannelData(c),voice=karaokeVoice.getChannelData(c);for(let i=0;i<out.length;i++)out[i]=music[i]+(voice[i]||0)*level;}return mix;}
async function processAudio(resume=false){
 if(!original)return;const previous=prepared,previousSettings=preparedSignature;pause();busy=true;controls();say('Preparando tu pista con el motor de audio…');
 try{
  if(!songId&&await autosaveCurrent()===false)throw Error('Guardá o descargá la canción antes de preparar el karaoke.');
  const key=signature(),cached=songId?await vault.getItem('prepared:'+songId):null;
  if(cached&&cached.signature===key){prepared=await ctx.decodeAudioData(await cached.blob.arrayBuffer());}
  else{if($('#mode').value!=='original')await ensureKaraoke();const base=mixedStem();if(shift===0){prepared=base;}else{const[blob]=await engineJob('pitch',base,shift);prepared=await ctx.decodeAudioData(await blob.arrayBuffer());await vault.putItem('prepared','prepared:'+songId,{signature:key},blob);}}
  preparedSignature=key;position=Math.min(position,prepared.duration);$('#toneValue').textContent=shift===0?'Original':(shift>0?'+':'')+shift;
  $('#songInfo').textContent=time(prepared.duration)+' · '+(shift===0?'Tono original':(shift>0?'+':'')+shift+' semitonos')+' · Lista para cantar';
  $('#reductionNote').textContent=$('#mode').value==='original'?'Para quitar al cantante, elegí Instrumental o pulsá Preparar karaoke.':'Voz e instrumentos separados con IA. Puede haber restos o artefactos según la grabación; compará con Original antes de guardarla para una presentación.';
  $('#voiceBlendValue').textContent=$('#voiceBlend').value+'%';if(await autosaveCurrent()!==false)say('Tu configuración quedó guardada. Escuchala antes de agregarla a tu repertorio de presentación.');
 }catch(e){prepared=previous;if(previousSettings){const old=JSON.parse(previousSettings);shift=old.shift;$('#mode').value=old.mode;$('#voiceBlend').value=old.voiceBlend;}else{shift=0;$('#mode').value='original';$('#voiceBlend').value=0;prepared=original;preparedSignature=signature();}$('#toneValue').textContent=shift===0?'Original':(shift>0?'+':'')+shift;$('#voiceBlendValue').textContent=$('#voiceBlend').value+'%';await savePreferences().catch(()=>{});say('No se cambió tu pista: '+e.message,true);}
 finally{busy=false;controls();}if(resume&&prepared)play();
}
$('#cancelEngine').onclick=async()=>{if(!engineActiveJob)return;const job=engineActiveJob;$('#cancelEngine').disabled=true;await fetch('./api/engine/jobs/'+job.id,{method:'DELETE',headers:job.headers}).catch(()=>{});$('#cancelEngine').disabled=false;};
$('#prepareAI').onclick=()=>{$('#mode').value='instrumental';processAudio(playing);};
$('#voiceBlend').oninput=()=>{$('#voiceBlendValue').textContent=$('#voiceBlend').value+'%';};$('#voiceBlend').onchange=()=>processAudio(playing);

async function loadFile(blob,name,saved=null){
 if(recording||busy)return;await lyrics.load(null);const token=++loadToken;stop();busy=true;controls();say('Abriendo tu canción…');
 try{if(blob.size>80*1024*1024)throw Error('large');init();const b=await ctx.decodeAudioData(await blob.arrayBuffer());if(token!==loadToken)return;if(b.duration>900)throw Error('long');original=b;prepared=null;currentBlob=blob;title=name;songId=saved?.id||null;shift=saved?.settings.shift||0;$('#mode').value=saved?.settings.mode||'original';$('#voiceBlend').value=saved?.settings.voiceBlend??0;for(const id of ['low','mid','high'])$('#'+id).value=saved?.settings[id]||0;$('#musicVolume').value=saved?.settings.volume??70;$('#layerVolume').value=saved?.settings.layerVolume??50;applyEq();$('#songName').textContent=name;position=0;await restoreKaraoke();busy=false;await processAudio();await restoreLayer();await lyrics.load(songId);}
 catch(e){say(e.message==='large'?'Este archivo supera 80 MB. Elegí una versión más liviana.':e.message==='long'?'Elegí una canción de hasta 15 minutos.':'No pudimos leer este formato. Probá MP3 o WAV; algunos MP4 no son compatibles.',true);}
 finally{busy=false;controls();}
}
$('#file').onchange=e=>{const f=e.target.files[0];if(f)loadFile(f,f.name);e.target.value='';};
$('#play').onclick=()=>playing?pause():play();$('#restart').onclick=()=>{const resume=playing;stop();if(resume)play();};
$('#seek').oninput=()=>{const resume=playing;pause();position=Number($('#seek').value)/1000*prepared.duration;if(resume)play();};
$('#mode').onchange=()=>processAudio(playing);$('#up').onclick=()=>{shift=Math.min(6,shift+1);processAudio(playing);};$('#down').onclick=()=>{shift=Math.max(-6,shift-1);processAudio(playing);};$('#resetTone').onclick=()=>{shift=0;processAudio(playing);};
function applyEq(){for(const [i,id]of ['low','mid','high'].entries()){const v=Number($('#'+id).value);$('#'+id+'Value').textContent=`${v>0?'+':''}${v} dB`;if(filters)filters[i].gain.setTargetAtTime(v,ctx.currentTime,.02);}const v=Number($('#musicVolume').value);$('#musicValue').textContent=v+'%';if(musicGain)musicGain.gain.setTargetAtTime(v/100,ctx.currentTime,.02);}
for(const id of ['low','mid','high','musicVolume'])$('#'+id).oninput=()=>{applyEq();queuePreferences();};$('#resetEq').onclick=()=>{for(const id of ['low','mid','high'])$('#'+id).value=0;applyEq();queuePreferences();};
function wav(buffer){const n=buffer.length,c=buffer.numberOfChannels,a=new ArrayBuffer(44+n*c*2),v=new DataView(a);const str=(at,s)=>[...s].forEach((x,i)=>v.setUint8(at+i,x.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+n*c*2,true);str(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,c,true);v.setUint32(24,buffer.sampleRate,true);v.setUint32(28,buffer.sampleRate*c*2,true);v.setUint16(32,c*2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*c*2,true);const channels=Array.from({length:c},(_,i)=>buffer.getChannelData(i));for(let i=0;i<n;i++)for(let ch=0;ch<c;ch++){const s=Math.max(-1,Math.min(1,channels[ch][i]));v.setInt16(44+(i*c+ch)*2,s<0?s*32768:s*32767,true);}return new Blob([a],{type:'audio/wav'});}
function filename(s){return s.replace(/\.[^.]+$/,'').replace(/[^\p{L}\p{N} _-]/gu,'').slice(0,80)||'Mi canción';}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('#downloadTrack').onclick=()=>openExport({kind:'track',name:title});
function closeMic(){if(recording)finishRecording();micStream?.getTracks().forEach(t=>t.stop());micStream=null;micSource?.disconnect();micGain?.disconnect();micMonitor?.disconnect();analyser=null;$('#meter').value=0;$('#monitor').checked=false;$('#monitor').disabled=true;$('#mic').textContent='Activar micrófono';$('#micStatus').textContent='El micrófono está apagado.';controls();}
$('#mic').onclick=async()=>{if(micStream)return closeMic();if(!navigator.mediaDevices?.getUserMedia){say('Para activar el micrófono, abrí MixLab desde localhost o una dirección HTTPS.',true);return;}$('#mic').disabled=true;try{init();await ctx.resume();micStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:false}});micSource=ctx.createMediaStreamSource(micStream);micGain=ctx.createGain();micGain.gain.value=Number($('#micVolume').value)/100;micMonitor=ctx.createGain();micMonitor.gain.value=0;analyser=ctx.createAnalyser();analyser.fftSize=256;micSource.connect(micGain);micGain.connect(recordMix);micGain.connect(micMonitor).connect(ctx.destination);micSource.connect(analyser);micStream.getAudioTracks()[0].onended=closeMic;$('#mic').textContent='Apagar micrófono';$('#micStatus').textContent='Micrófono encendido. Hablá: la barra debería moverse.';$('#monitor').disabled=false;$('#recordStatus').textContent=prepared?'Todo listo para grabar tu versión.':'Elegí una canción para grabar.';say('Micrófono listo. Usá auriculares antes de activar la escucha de tu voz.');}catch{say('No pudimos activar el micrófono. Revisá el permiso del navegador y que esté conectado.',true);}finally{controls();}};
$('#micVolume').oninput=()=>{const v=Number($('#micVolume').value);$('#micValue').textContent=v+'%';if(micGain)micGain.gain.setTargetAtTime(v/100,ctx.currentTime,.02);};
$('#monitor').onchange=()=>{if(micMonitor)micMonitor.gain.setTargetAtTime($('#monitor').checked?1:0,ctx.currentTime,.02);};
function finishRecording(){if(!recording)return;recording=false;recordSaving=true;recorder.stop();pause();controls();$('#recordStatus').textContent='Preparando tu grabación…';}
$('#record').onclick=async()=>{
 if(!prepared||!micStream||recordSaving)return;
 if(!window.MediaRecorder)return say('Este navegador no permite grabar. Probá uno actualizado.',true);
 if((await vault.usage()).recordings>=10)return say('Ya tenés 10 grabaciones. Descargá y quitá una antes de empezar otra.',true);
 try{
  stop();await ctx.resume();const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=mime?new MediaRecorder(recordBus.stream,{mimeType:mime}):new MediaRecorder(recordBus.stream);
  const chunks=[],parts=[],id=crypto.randomUUID(),name=title,format=recorder.mimeType,created=Date.now();let chunkQueue=Promise.resolve(),partIndex=0;
  recorder.ondataavailable=e=>{if(!e.data.size)return;chunks.push(e.data);const partId='part:'+id+':'+partIndex++;chunkQueue=chunkQueue.then(async()=>{await vault.putItem('draft',partId,{session:id,name,format,created,index:parts.length},e.data);parts.push(partId);}).catch(()=>{say('No pudimos guardar un fragmento. Terminá y descargá la grabación antes de cerrar.',true);});};
  recorder.onstop=async()=>{recordSaving=true;controls();await chunkQueue;const blob=new Blob(chunks,{type:format});try{await vault.putItem('recording',id,{name,created,format},blob);for(const partId of parts)await vault.removeItem(partId);await renderRecordings();$('#recordStatus').textContent='Guardada en tu perfil. Podés volver a escucharla sin conexión.';say('Tu grabación quedó guardada en este perfil.');}catch(e){renderRecordingCard({id,name,created,format,blob},false);say(e.message+' Descargá esta grabación antes de cerrar.',true);}finally{recordSaving=false;controls();refreshUsage();}};
  recording=true;recorder.start(5000);await play();controls();$('#recordStatus').textContent='● Grabando. Guardamos fragmentos cada cinco segundos.';say('Estás grabando. Al terminar, pulsá Terminar grabación.');
 }catch{recording=false;if(recorder?.state==='recording')recorder.stop();controls();say('No se pudo iniciar la grabación. Revisá el micrófono e intentá otra vez.',true);}
};
$('#stopRecord').onclick=finishRecording;
$('#demo').onclick=async()=>{if(busy||recording)return;await lyrics.load(null);init();stop();const sr=24000,n=sr*16,b=ctx.createBuffer(2,n,sr);for(let ch=0;ch<2;ch++){const d=b.getChannelData(ch);for(let i=0;i<n;i++){const t=i/sr,p=t%.6,f=[130.81,146.83,164.81,110][Math.floor(t/2.4)%4];const noteTime=t%1.2,envelope=Math.min(1,noteTime/.015)*Math.exp(-noteTime*3.8);d[i]=envelope*(.16*Math.sin(2*Math.PI*f*t)+.07*Math.sin(2*Math.PI*f*1.5*t+ch*.03)+.035*Math.sin(2*Math.PI*f*2*t))+.06*Math.sin(2*Math.PI*55*p)*Math.exp(-p*25);d[i]*=Math.min(1,(16-t)/.3);}}stopLayer();layerBuffer=null;$('#layerName').textContent='Sin segunda pista.';currentBlob=wav(b);original=b;karaokeMusic=null;karaokeVoice=null;preparedSignature=null;title='Acompañamiento suave · ejemplo';songId=null;shift=0;$('#mode').value='original';$('#songName').textContent=title;position=0;await processAudio();};
// Profile persistence and export live below.


setInterval(()=>{if(prepared){const p=current();$('#clock').textContent=time(p)+' / '+time(prepared.duration);$('#seek').value=p/prepared.duration*1000;}if(analyser){const a=new Float32Array(analyser.fftSize);analyser.getFloatTimeDomainData(a);$('#meter').value=Math.min(1,Math.sqrt(a.reduce((s,v)=>s+v*v,0)/a.length)*3);}},120);
window.addEventListener('beforeunload',e=>{if(recording||recordSaving||document.querySelector('.unsaved-recording')){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>{micStream?.getTracks().forEach(t=>t.stop());urls.forEach(u=>URL.revokeObjectURL(u));});
let preferencesTimer,exportTarget,installPrompt,recordingUrls=[];

async function refreshUsage(){if(!vault.activeProfile())return;const u=await vault.usage();$('#recordingCount').textContent=`${u.recordings} de 10 grabaciones guardadas`;$('#spaceStatus').textContent=`${(u.bytes/1024/1024).toFixed(1)} MB de 400 MB en tu perfil · ${u.songs}/15 canciones · ${u.recordings}/10 grabaciones`;
 $('#record').disabled=$('#record').disabled||u.recordings>=10;}
function queuePreferences(){clearTimeout(preferencesTimer);if(!songId||!vault.activeProfile())return;preferencesTimer=setTimeout(()=>savePreferences().catch(e=>say('No pudimos guardar tus ajustes: '+e.message,true)),600);}
async function savePreferences(){if(!songId)return;const id=songId,prefs=settings();await vault.putItem('settings','prefs:'+id,prefs);await vault.putItem('settings','last-session',{songId:id});}
async function autosaveCurrent(){
 if(!vault.activeProfile()||!currentBlob)return;
 try{if(!songId){const id=crypto.randomUUID();await vault.putItem('song',id,{name:title,created:Date.now()},currentBlob);songId=id;}await savePreferences();await renderSongs();await refreshUsage();}
 catch(e){say('La canción está lista, pero no se pudo guardar: '+e.message+' Descargá una copia.',true);return false;}
}
$('#saveSong').onclick=async()=>{try{if(await autosaveCurrent()!==false)say('Tu canción y tus ajustes están guardados en este perfil.');}catch{}};
async function renderSongs(){
 if(!vault.activeProfile())return;const list=await vault.getItems('song');$('#songs').replaceChildren();
 if(!list.length){const p=document.createElement('p');p.className='empty';p.textContent='Elegí una canción: quedará guardada acá automáticamente.';$('#songs').append(p);}
 for(const song of list){const row=document.createElement('div');row.className='song-row';const open=document.createElement('button');open.textContent=song.name;
 open.onclick=async()=>{if(recording||recordSaving||busy)return say('Terminá la tarea actual antes de cambiar de canción.');await flushPreferences();const saved=await vault.getItem(song.id),prefs=await vault.getItem('prefs:'+song.id);loadFile(saved.blob,saved.name,{id:song.id,settings:prefs?.value||{}});};
 const remove=document.createElement('button');remove.textContent='Quitar';remove.setAttribute('aria-label','Quitar '+song.name+' de mi repertorio');
 remove.onclick=async()=>{if(recording||recordSaving||busy)return;try{const saved=await vault.getItem(song.id),prefs=await vault.getItem('prefs:'+song.id),layer=await vault.getItem('layer:'+song.id);const extras=[];for(const prefix of ['stem-i:','stem-v:','prepared:','lyrics:']){const item=await vault.getItem(prefix+song.id);if(item)extras.push({prefix,item});await vault.removeItem(prefix+song.id);}await vault.removeItem('layer:'+song.id);await vault.removeItem(song.id);await vault.removeItem('prefs:'+song.id);if(songId===song.id){pause();stopLayer();layerBuffer=null;$('#layerName').textContent='Sin segunda pista.';songId=null;await vault.removeItem('last-session');}await renderSongs();await refreshUsage();const undo=document.createElement('button');undo.textContent='Deshacer: recuperar '+song.name;undo.onclick=async()=>{await vault.putItem('song',song.id,{name:saved.name,created:saved.created},saved.blob);if(prefs)await vault.putItem('settings','prefs:'+song.id,prefs.value);if(layer)await vault.putItem('layer','layer:'+song.id,{name:layer.name},layer.blob);for(const {prefix,item}of extras)await vault.putItem(prefix==='prepared:'?'prepared':prefix==='lyrics:'?'lyrics':'stem',prefix+song.id,prefix==='lyrics:'?{entries:item.entries,offset:item.offset}:{role:item.role,signature:item.signature},item.blob);await renderSongs();await refreshUsage();};$('#songs').prepend(undo);say('Quitaste la canción. Podés deshacerlo antes de salir de esta pantalla.');}catch(e){say(e.message,true);}};
 row.append(open,remove);$('#songs').append(row);}
}
async function renderRecordings(){for(const u of recordingUrls)URL.revokeObjectURL(u);recordingUrls=[];$('#recordings').replaceChildren();const rows=await vault.getItems('recording');for(const meta of rows.sort((a,b)=>b.created-a.created)){const r=await vault.getItem(meta.id);renderRecordingCard(r,true);}await refreshUsage();}
function renderRecordingCard(r,saved){const card=document.createElement('div');card.className='recording'+(saved?'':' unsaved-recording');const strong=document.createElement('strong');strong.textContent=r.name+' · '+new Date(r.created).toLocaleString('es');const audio=document.createElement('audio');audio.controls=true;audio.preload='none';const url=URL.createObjectURL(r.blob);recordingUrls.push(url);audio.src=url;const exp=document.createElement('button');exp.textContent='↓ Exportar mi grabación';exp.onclick=()=>openExport({kind:'recording',name:r.name,blob:r.blob});card.append(strong,audio,exp);if(saved){const remove=document.createElement('button');remove.textContent='Quitar';remove.onclick=async()=>{if(recording||recordSaving||busy)return;await vault.removeItem(r.id);await renderRecordings();const undo=document.createElement('button');undo.textContent='Deshacer: recuperar grabación';undo.onclick=async()=>{try{await vault.putItem('recording',r.id,{name:r.name,format:r.format,created:r.created},r.blob);await renderRecordings();say('Grabación recuperada.');}catch(e){say(e.message,true);}};$('#recordings').prepend(undo);say('Grabación quitada. Podés deshacerlo acá.');};card.append(remove);}$('#recordings').append(card);}
async function recoverFragments(){const drafts=await vault.getItems('draft'),groups=new Map();for(const d of drafts){if(!groups.has(d.session))groups.set(d.session,[]);groups.get(d.session).push(d);}for(const[id,parts]of groups){if((await vault.usage()).recordings>=10){say('Hay una grabación interrumpida pendiente. Liberá un lugar para recuperarla al volver a ingresar.',true);break;}const existing=await vault.getItem(id);if(!existing){const sorted=parts.sort((a,b)=>a.index-b.index),blobs=[];for(const p of sorted)blobs.push((await vault.getItem(p.id)).blob);const first=sorted[0];await vault.putItem('recording',id,{name:first.name+' · recuperada',created:first.created,format:first.format},new Blob(blobs,{type:first.format}));say('Recuperamos fragmentos de una grabación interrumpida. Escuchala para comprobarla.');}for(const p of parts)await vault.removeItem(p.id);}}
async function flushPreferences(){clearTimeout(preferencesTimer);if(songId&&vault.activeProfile())await savePreferences();}
async function enterProfile(){const p=vault.activeProfile();$('#auth').hidden=true;$('#main').hidden=false;$('#sessionBar').hidden=false;$('#profileEmail').textContent=p.email;$('#password').value='';await recoverFragments();await renderSongs();await renderRecordings();say('Estás en tu espacio personal. Tus canciones guardadas funcionan sin conexión.');const last=await vault.getItem('last-session');if(last?.value?.songId){const song=await vault.getItem(last.value.songId),prefs=await vault.getItem('prefs:'+last.value.songId);if(song)await loadFile(song.blob,song.name,{id:song.id,settings:prefs?.value||{}});}controls();refreshUsage();}
$('#authForm').onsubmit=async e=>{e.preventDefault();const create=e.submitter?.id==='register';$('#login').disabled=$('#register').disabled=true;$('#authStatus').textContent=create?'Creando tu espacio cifrado…':'Abriendo tu espacio…';try{if(!isSecureContext||!crypto.subtle)throw Error('Abrí MixLab desde localhost o HTTPS para usar perfiles protegidos.');await(create?vault.createProfile($('#email').value,$('#password').value):vault.login($('#email').value,$('#password').value));await enterProfile();$('#authStatus').textContent='';}catch(err){$('#authStatus').textContent=err.message;}finally{$('#login').disabled=$('#register').disabled=false;}};
$('#showPassword').onclick=()=>{const show=$('#password').type==='password';$('#password').type=show?'text':'password';$('#showPassword').textContent=show?'Ocultar':'Mostrar';$('#showPassword').setAttribute('aria-pressed',String(show));};
$('#logout').onclick=async()=>{if(recording||recordSaving||busy)return;try{await flushPreferences();closeMic();stop();await ctx?.close();vault.lock();location.reload();}catch(e){say('No pudimos cerrar el perfil sin guardar. '+e.message,true);}};
$('#backup').onclick=async()=>{if(recording||recordSaving||busy)return;busy=true;controls();try{await flushPreferences();download(await vault.exportBackup(),'MixLab - copia cifrada - '+new Date().toISOString().slice(0,10)+'.json');say('Copia cifrada preparada. Guardala con tu contraseña en un lugar seguro.');}catch(e){say('No pudimos crear la copia: '+e.message,true);}finally{busy=false;controls();}};
$('#restoreBackup').onclick=async()=>{const f=$('#backupFile').files[0];if(!f){$('#authStatus').textContent='Elegí primero una copia de seguridad.';return;}$('#restoreBackup').disabled=true;try{await vault.restoreBackup(f,$('#password').value);await enterProfile();}catch(e){$('#authStatus').textContent=e.message;}finally{$('#restoreBackup').disabled=false;}};
$('#persist').onclick=async()=>{try{const ok=await navigator.storage?.persist?.();$('#storageStatus').textContent=ok?'El navegador concedió guardado persistente. Igual conservá una copia de seguridad.':'El navegador no concedió protección adicional. Conservá copias descargadas y evitá limpiar los datos de MixLab.';}catch{$('#storageStatus').textContent='No se pudo solicitar protección. Hacé una copia de seguridad.';}};
function openExport(target){if(recording||recordSaving||busy)return;exportTarget=target;$('#exportStatus').textContent='';$('#exportFormat').value='mp3';$('#exportFormat option[value=original]').disabled=target.kind!=='recording';$('#exportDialog').showModal();}
$('#cancelExport').onclick=()=>$('#exportDialog').close();
async function renderTrack(){const offline=new OfflineAudioContext(2,prepared.length,prepared.sampleRate),n=offline.createBufferSource();n.buffer=prepared;const eq=makeEq(offline),g=offline.createGain(),limiter=cleanLimiter(offline);g.gain.value=Number($('#musicVolume').value)/100;n.connect(eq[0]);eq[2].connect(g).connect(limiter).connect(offline.destination);n.start();if(layerBuffer){const extra=offline.createBufferSource(),gain=offline.createGain();extra.buffer=layerBuffer;gain.gain.value=Number($('#layerVolume').value)/100;extra.connect(gain).connect(limiter);extra.start();}return offline.startRendering();}
async function encodeMp3(buffer){const worker=new Worker('./mp3-worker.js');try{return await new Promise((resolve,reject)=>{worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data.blob);worker.onerror=()=>reject(Error('No se pudo abrir el codificador MP3. Comprobá que MixLab terminó de prepararse sin conexión.'));const channels=Array.from({length:Math.min(2,buffer.numberOfChannels)},(_,i)=>buffer.getChannelData(i).slice());worker.postMessage({channels,sampleRate:buffer.sampleRate},channels.map(c=>c.buffer));});}finally{worker.terminate();}}
$('#confirmExport').onclick=async()=>{if(!exportTarget)return;busy=true;controls();$('#confirmExport').disabled=$('#cancelExport').disabled=true;$('#exportStatus').textContent='Preparando tu archivo… Podés esperar acá.';try{let blob,ext;const format=$('#exportFormat').value;if(format==='original'){blob=exportTarget.blob;ext=blob.type.includes('mp4')?'m4a':'webm';}else{init();const buffer=exportTarget.kind==='track'?await renderTrack():await ctx.decodeAudioData(await exportTarget.blob.arrayBuffer());blob=format==='mp3'?await encodeMp3(buffer):wav(buffer);ext=format;}download(blob,filename(exportTarget.name)+(exportTarget.kind==='track'?' - karaoke.':' - mi voz.')+ext);$('#exportStatus').textContent='Archivo preparado. Revisá Descargas para conservarlo.';say('Exportación preparada. Tus archivos guardados siguen en tu perfil.');}catch(e){$('#exportStatus').textContent='No se pudo exportar: '+e.message+' Probá WAV o el formato original.';}finally{busy=false;controls();$('#confirmExport').disabled=$('#cancelExport').disabled=false;}};
$('#exportDialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}};
function connectionState(ready){$('#connection').textContent=ready?(navigator.onLine?'Lista para usar sin conexión · tus canciones quedan en este dispositivo':'Sin conexión · tu repertorio y tus grabaciones siguen disponibles'):'No se confirmó la preparación sin conexión. Abrí MixLab por localhost o HTTPS.';}
async function boot(){if('serviceWorker'in navigator&&isSecureContext){try{await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;connectionState(true);}catch{connectionState(false);}}else connectionState(false);window.addEventListener('online',()=>connectionState(!!navigator.serviceWorker?.controller));window.addEventListener('offline',()=>connectionState(!!navigator.serviceWorker?.controller));}

function stopLayer(){if(layerSource){try{layerSource.stop();}catch{}layerSource.disconnect();layerSource=null;}}
function startLayer(offset){stopLayer();if(!layerBuffer||offset>=layerBuffer.duration)return;layerSource=ctx.createBufferSource();layerSource.buffer=layerBuffer;layerGain=ctx.createGain();layerGain.gain.value=Number($('#layerVolume').value)/100;layerSource.connect(layerGain).connect(output);layerSource.start(0,offset);}
async function restoreLayer(){stopLayer();layerBuffer=null;$('#layerName').textContent='Sin segunda pista.';$('#layerValue').textContent=$('#layerVolume').value+'%';if(!songId)return;const layer=await vault.getItem('layer:'+songId);if(layer){layerBuffer=await ctx.decodeAudioData(await layer.blob.arrayBuffer());$('#layerName').textContent=layer.name;}}
$('#layerVolume').oninput=()=>{$('#layerValue').textContent=$('#layerVolume').value+'%';if(layerGain)layerGain.gain.setTargetAtTime(Number($('#layerVolume').value)/100,ctx.currentTime,.02);queuePreferences();};
$('#layerFile').onchange=async e=>{const f=e.target.files[0];if(!f||busy||recording)return;pause();busy=true;controls();try{if(f.size>80*1024*1024)throw Error('Elegí un archivo de hasta 80 MB.');const decoded=await ctx.decodeAudioData(await f.arrayBuffer());if(decoded.duration>900)throw Error('Elegí un audio de hasta 15 minutos.');if(!songId)throw Error('Guardá primero la canción principal.');await vault.putItem('layer','layer:'+songId,{name:f.name},f);layerBuffer=decoded;$('#layerName').textContent=f.name;say('Segunda pista guardada. Ambas se escucharán juntas y entrarán en la exportación.');await refreshUsage();}catch(err){say('No se pudo sumar la pista: '+err.message,true);}finally{busy=false;e.target.value='';controls();}};
$('#removeLayer').onclick=async()=>{stopLayer();layerBuffer=null;$('#layerName').textContent='Sin segunda pista.';if(songId)await vault.removeItem('layer:'+songId);refreshUsage();};

if(!localMotorHost){$('#editionNotice').hidden=false;$('#reductionNote').textContent='Para separar una canción nueva, usá la edición de computadora. Esta web reutiliza las pistas preparadas que importes.';$('#toneHelp').textContent='En esta web se conserva el tono preparado en la computadora. Importá una copia cifrada del repertorio o elegí un archivo ya adaptado.';}
$('#installIntro').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}else{$('#installMessage').textContent=matchMedia('(display-mode: standalone)').matches?'MixLab ya está abierto como aplicación instalada.':'Usá el menú de tu navegador para instalar. En iPhone/iPad: Compartir → Añadir a pantalla de inicio. Primero esperá Lista para usar sin conexión.';}};
const lyrics=createLyrics({vault,getSongId:()=>songId,getPosition:()=>prepared?current():0,togglePlayback:()=>{if(!prepared)return say('Elegí una canción primero.');return playing?pause():play();},canEdit:()=>!recording&&!recordSaving&&!busy,download,say});
boot();controls();


